Q: I want to make my JavaScript code optimize using arrays and loop (for loop) A: <p>If we want to use a loop instead we need to:</p>
<ul>
<li>Create an array of the correct answers.</li>
<li>Iterate through each question with an index starting from <code>1</code>.</li>
<li>Append the index to the selectors.</li>
</ul>
<p><strong>This look like this:</strong></p>
<pre class="lang-js prettyprint-override"><code>let correctAnswers = [&quot;carefully&quot;, &quot;careful&quot;, &quot;quickly&quot;, &quot;quick&quot;, &quot;tired&quot;];

for (let i = 1; i &lt;= 5; i++) {
    var a = document.getElementById(&quot;solution1_&quot; + i);

    if (a.value.toLowerCase().trim() === correctAnswers[i - 1]) {
        var element = document.getElementById(&quot;solution1_&quot; + i);
        element.classList.toggle(&quot;ex_textfield-right&quot;);

        var element = document.getElementById(&quot;counter_&quot; + i);
        element.classList.toggle(&quot;counter-right&quot;);
    } else {
        var element = document.getElementById(&quot;counter_&quot; + i);
        element.classList.toggle(&quot;counter-wrong&quot;);

        var element = document.getElementById(&quot;solution1_&quot; + i);
        element.classList.toggle(&quot;ex_textfield-wrong&quot;);

        var e = document.getElementById(&quot;check-ans-&quot; + i);
        e.style.display = e.style.display != &quot;block&quot; ? &quot;block&quot; : &quot;none&quot;;
    }
}
</code></pre>
<p><strong>Full code:</strong>
<div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
