Q: Javascript array assigning index value is not working A: <p>The issue is you are trying to access the titles before receiving the response from the API. In javascript we call it asynchronous code. You can make your code synchronous by waiting for its execution to finish. You can use async/await syntax to deal with this.</p>
<p>You can try running the below code snippet. You will see some delay on the console log.</p>
<p>Your fetch request API call is awaited using <code>await</code>. In order for you to use await inside a function, you need to add <code>async keyword on the function</code>.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;!DOCTYPE html&gt;
    &lt;html&gt;
    &lt;body&gt;

        &lt;div id="pred"&gt;


        &lt;/div&gt;


        &lt;script&gt;
        async function fetchMoviesJSON(url) {
            const response = await fetch(url);
            const movies = await response.json();
            return movies;
        }

        async function fetchTitles() {
            let ids = "[19995, 440, 679, 17663, 602, 7450, 44943,                             34851, 11551, 76757, 11260]";

            let data = JSON.parse(ids.replaceAll("\""));

            let titles = [];
            let posters = [];

            const my_api_key = '34b55fa7f2d2346aa1045ed4cc22bd12';
            const url1 = 'https://api.themoviedb.org/3/movie/';
            const url2 = "https://image.tmdb.org/t/p/w500/" ;
            for (i = 0 ; i &lt; data.length ; i++) {
                url = url1 + data[i] + '?api_key=' + my_api_key;
                try {
                  const movieResponse = await fetchMoviesJSON(url);
                  titles.push(movieResponse.title);
                  posters.push(url2 + (movieResponse.poster_path));
                } catch (err) {
                  console.log(err);
                }
                const my_M = `
                &lt;h1 style="color:blue ;"&gt;
                        &lt;span&gt;${titles[0]}&lt;/span&gt;
                &lt;/h1&gt;
                `;
                document.getElementById("pred").innerHTML = my_M;
            }
            console.log(titles);
            console.log(posters)
        }
        fetchTitles()
      &lt;/script&gt;



    &lt;/body&gt;

    &lt;/html&gt;</code></pre>
</div>
</div>
</p>

